CREATE VIEW MOG_KH_SUB AS SELECT        CODE, SUM(MEGHk - MEGH_MAR) AS MEG, SUM((MEGHk - MEGH_MAR) * dbo.INVO_LST.AVRAGE) AS SumOfMABL_K FROM dbo.INVO_LST WHERE        (TAG = 1) OR   (TAG = 7) OR   (TAG = 9) OR   (TAG = 22) OR   (TAG = 24) GROUP BY CODE HAVING (SUM(MEGHk - MEGH_MAR) <> 0) UNION SELECT        dbo.ANBGRD_LST.CODE, SUM((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * - 1) AS MEG, SUM(dbo.ANBGRD_LST.MABL) AS mablk FROM            dbo.ANBGRD_LST INNER JOIN   dbo.ANBGRD_HEAD ON dbo.ANBGRD_LST.GRD_NUM = dbo.ANBGRD_HEAD.GRD_NUM WHERE (Not (dbo.ANBGRD_HEAD.N_S Is Null)) And ((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * -1 > 0)GROUP BY dbo.ANBGRD_LST.CODE
